// Number

let length = 16;

let weight = 7.5;

// BigInt

let x = 1234567890123456789012345n;

let y = BigInt(1234567890123456789012345)

// Strings

let color = "Yellow";

let lastName = "Johnson";

// Boolean

let x = true;

let y = false;

// Undefined

let x;

let y;

// Null

let x = null;

let y = null;

// Symbol

const x = Symbol();

const y = Symbol();

// Object

const person = {firstName:"John", lastName:"Doe"};

// Array Object

const cars = ["Saab", "Volvo", "BMW"];

// Date Object

const date = new Date("2022-03-25");
